'use client'

import { logout } from '@/lib/api'

export default function LogoutButton() {
	async function handleLogout() {
		await logout()
		window.location.href = '/login'
	}

	return (
		<button
			onClick={handleLogout}
			style={{
				padding: '6px 12px',
				background: '#eee',
				border: '1px solid #ccc',
				cursor: 'pointer',
			}}
		>
			🚪 Вийти
		</button>
	)
}